function restore(){for(const el of $$('[data-field]'))el.value=state.answers[el.dataset.field]??'';for(const el of $$('.feedback'))el.textContent='';for(const el of $$('[data-complete]'))el.checked=!!state.completed[el.dataset.complete];for(const el of $$('.teacher-only'))el.hidden=!teacher;$('#teacherBanner').hidden=!teacher;$('#identity').textContent=teacher?'Teacher preview':state.name+' · '+state.className;for(const k of ['main1','main2'])showSub(k,subpages[k],false);for(const k of ['flat','nested']){const t=state.tutor[k]||{};$(`#scenario-${k}`).value=t.scenario||(k==='flat'?'14':'accepted');drawTutor(k,t.step||0,false);}refreshReflections();renderEvidence();paperStatus();}
function go(id){if(!stages.some(x=>x[0]===id))id='overview';stageNow=id;for(const [key]of stages)$('#'+key).hidden=key!==id;for(const b of $$('#route button'))b.setAttribute('aria-current',b.dataset.go===id?'step':'false');$('#route').hidden=true;$('#menu').setAttribute('aria-expanded','false');$$('[data-back]').forEach(b=>b.disabled=id==='overview');$$('[data-next]').forEach(b=>b.hidden=id==='report');if(id==='report')renderReport();save();window.scrollTo({top:0,behavior:'instant'});$('#lesson').focus({preventScroll:true});}
function showSub(id,num,scroll=true){subpages[id]=num;$$(`[data-panel^="${id}:"]`).forEach(el=>el.hidden=el.dataset.panel!==`${id}:${num}`);$$(`[data-sub^="${id}:"]`).forEach(b=>b.setAttribute('aria-current',b.dataset.sub===`${id}:${num}`?'true':'false'));if(scroll)$('#'+id+' .subnav').scrollIntoView({block:'start',behavior:'instant'});}
function score(id){const items=groups[id];let attempted=0,correct=0;const snapshot={};for(const item of items){const value=state.answers[item.id]||'';snapshot[item.id]=value;if(value)attempted++;const good=value===item.answer;if(good)correct++;$('#fb-'+item.id).textContent=!value?'Choose an answer when you are ready.':`${good?'Correct.':'Review this one.'} ${item.explanation}`;}
$('#result-'+id).textContent=`${correct} correct of ${items.length}; ${attempted} attempted. Missing answers are not counted as wrong attempts. You may improve and check again.`;
state.attempts.push({group:id,time:new Date().toISOString(),answers:snapshot,correct,total:items.length,attempted});save();}
function refreshReflections(){if(!state)return;for(const w of ['before','after']){let chunks=[];for(const area of ['Knowledge','Skills','Understanding']){const ids=targets.filter(x=>x[1]===area).map(x=>x[0]);const n=v=>ids.filter(id=>state.answers[`${w}-${id}`]===v).length;const filled=ids.filter(id=>state.answers[`${w}-${id}`]).length;chunks.push(`${area}: ${n('independent')}/2 independent, ${n('support')}/2 with support, ${n('not-yet')}/2 not yet; ${2-filled} unselected.`);}$('#'+w+'-summary').textContent=chunks.join(' ')+' These are self-reports, not test marks.';}
const id=state.answers['pit-priority'];const phase=state.answers['phase-'+id];const acts={new:'Work through one more short example using the model, then try it without the model.',consolidating:'Explain your reasoning and test a different boundary independently.',treading:'Ask for the paper or find a counterexample to an incorrect condition.',help:'Pause and ask your teacher to model one condition or one executed line. Say exactly where the meaning became unclear.'};$('#nextAction').textContent=id?(id+': '+(acts[phase]||'Choose a learning phase for this target, then decide your next step.')):'Choose a target above to receive a specific next-step prompt.';}
const paths={flat:{'14':[[1,'Assign the integer 14 to age. No group has been output.'],[2,'14 >= 16 is False. Skip line 3 and check the elif condition.'],[4,'14 >= 14 is True. Select the Intermediate branch.'],[5,'Output: Intermediate group. Skip the else branch (lines 6–7); this chain has finished.']], '13':[[1,'Assign 13 to age.'],[2,'13 >= 16 is False. Skip line 3.'],[4,'13 >= 14 is False. No earlier branch matched.'],[6,'Take the fallback else branch. Else has no new condition.'],[7,'Output: Junior group. The chain has finished.']], '16':[[1,'Assign 16 to age.'],[2,'16 >= 16 is True. Select the first branch.'],[3,'Output: Senior group. Skip lines 4–7; the elif condition is not evaluated.']]},nested:{accepted:[[1,'Assign age = 14.'],[2,'Assign permission = True.'],[3,'Assign cancelled = False.'],[4,'not cancelled is True. True and True is True, so enter the outer block.'],[5,'14 >= 16 is False. Skip line 6.'],[7,'14 >= 14 is True. Select the Intermediate branch.'],[8,'Output: Intermediate group. Skip the inner fallback and the outer else.']],refused:[[1,'Assign age = 16.'],[2,'Assign permission = False.'],[3,'Assign cancelled = False.'],[4,'Permission is False, so the AND condition is False. Python need not evaluate the right-hand part. Skip the entire inner block, lines 5–10.'],[11,'Take the outer else, aligned with line 4.'],[12,'Output: Booking cannot proceed. The age comparisons were never reached.']],cancelled:[[1,'Assign age = 13.'],[2,'Assign permission = True.'],[3,'Assign cancelled = True.'],[4,'not cancelled is False. True and False is False. Skip lines 5–10.'],[11,'Take the outer else.'],[12,'Output: Booking cannot proceed. The workshop is cancelled, so no group is allocated.']]}};
function tutorCode(kind,scenario){if(kind==='flat')return flat.replace('age = 14','age = '+scenario);return nested.replace('age = 14','age = '+({accepted:14,refused:16,cancelled:13}[scenario])).replace('permission = True','permission = '+(scenario==='refused'?'False':'True')).replace('cancelled = False','cancelled = '+(scenario==='cancelled'?'True':'False'));}
function drawTutor(kind,index=0,record=true){const scenario=$('#scenario-'+kind).value;const p=paths[kind][scenario];index=Math.max(0,Math.min(index,p.length-1));const [line,explanation]=p[index];$('#lines-'+kind).innerHTML=tutorCode(kind,scenario).split('\n').map((t,i)=>`<div class="code-line ${i+1===line?'active':''}" ${i+1===line?'aria-current="step"':''}><span class="line-num">${i+1}</span><span>${esc(t)}</span></div>`).join('');$('#explain-'+kind).textContent=`Step ${index+1} of ${p.length} · Line ${line}. ${explanation}`;$(`[data-tutor-prev="${kind}"]`).disabled=index===0;$(`[data-tutor-next="${kind}"]`).disabled=index===p.length-1;if(state&&record){const old=state.tutor[kind]||{};state.tutor[kind]={scenario,step:index,visited:[...new Set([...(old.visited||[]),scenario+':'+line])]};}}
async function addImages(files,stage){for(const f of files){if(!['image/png','image/jpeg','image/webp'].includes(f.type)){statusImage(stage,'Only PNG, JPEG and WebP images are supported.');continue;}if(f.size>8*1024*1024){statusImage(stage,'This image is over 8 MB. Please choose a smaller image; it was not added.');continue;}if(evidence.filter(x=>x.stage===stage).length>=6){statusImage(stage,'Six images are already attached to this stage. Remove one if needed.');break;}imageBusy++;try{const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});await new Promise((res,rej)=>{const img=new Image();img.onload=res;img.onerror=()=>rej(new Error('Image could not be decoded.'));img.src=data;});evidence.push({id:crypto.randomUUID?.()||String(Date.now()+Math.random()),stage,name:f.name||'Pasted image',data,caption:'',time:new Date().toISOString()});renderEvidence();try{await imagesSave();statusImage(stage,teacher?'Image attached for this preview.':'Image attached and saved on this device.');}catch(e){warn('The image is attached for this session but could not be saved in browser storage. Download a full backup before closing the tab.');statusImage(stage,'Attached in memory only — download a backup.');}}catch(e){statusImage(stage,'Could not read this image. Try a PNG or JPEG screenshot.');}finally{imageBusy--;}}}
function statusImage(stage,msg){$('#image-status-'+stage).textContent=msg;}
function renderEvidence(){for(const s of ['main1','main2','plenary']){const host=$('#images-'+s);host.replaceChildren();for(const item of evidence.filter(x=>x.stage===s)){const f=document.createElement('figure'),img=document.createElement('img');img.src=item.data;img.alt=item.caption||item.name;f.append(img);const label=document.createElement('label');label.textContent='Caption: what does this evidence show?';const inp=document.createElement('input');inp.value=item.caption;inp.maxLength=400;label.append(inp);f.append(label);inp.addEventListener('input',()=>{item.caption=inp.value;img.alt=item.caption||item.name;imagesSave().catch(()=>warn('Image caption could not be saved. Download a backup.'));});const b=document.createElement('button');b.textContent='Remove this image';b.type='button';b.onclick=async()=>{if(!confirm('Remove this attached image? Your original file is not deleted.'))return;evidence=evidence.filter(x=>x.id!==item.id);renderEvidence();try{await imagesSave();}catch{warn('The image removal could not be saved. Download a fresh backup.');}};f.append(b);host.append(f);}}}
function paperStatus(){if(!state)return;const last=state.paper.at(-1);$('#paperStatus').textContent=last?'Recorded: '+last.action+'. No message has been sent to the teacher.':'No paper requested yet.';$('#paperSignal').hidden=last?.action!=='Paper requested';}
function prettyValue(id,v){const el=document.getElementById(id);if(el?.tagName==='SELECT')return [...el.options].find(x=>x.value===v)?.textContent||v;return v;}
function reportHTML(){let html=`<h1>Making decisions · Lesson evidence</h1><p><strong>${esc(state.name)} · ${esc(state.className)}</strong><br>Year 10 · Week 4 · Sessions 1 + 2 · OxfordAQA 9210<br>Export prepared: ${esc(new Date().toLocaleString())}${teacher?'<br><strong>TEACHER PREVIEW — not a student submission</strong>':''}</p><p><strong>WAGBA:</strong> writing clear conditions and making correct decisions.</p><p>Specification: 3.2.2, 3.2.4, 3.2.5; supporting 3.1.1. Completion, self-ratings and automatic practice feedback are different evidence; none alone proves mastery.</p>`;
for(const [id,label]of stages.filter(x=>x[0]!=='report')){html+=`<h2>${esc(label)}</h2><p class="small">Student marked reviewed: ${state.completed[id]?'Yes':'Not yet'}</p>`;if(id==='overview')html+=`<p>Scenario: workshop ages 12–18; accepted bookings require permission and not cancelled. Age groups: 16–18 Senior; 14–15 Intermediate; 12–13 Junior. Valid starting data assumed.</p><ul>${targets.map(([key,area,t])=>`<li>${key} · ${area}: ${t}</li>`).join('')}</ul>`;
for(const [key,m]of Object.entries(registry).filter(([,m])=>m.stage===id)){const v=state.answers[key];html+=`<section class="report-entry"><h3>${esc(m.label)}</h3>${m.kind==='code'?'<pre>':'<div class="report-answer">'}${v?esc(prettyValue(key,v)):'Not answered yet.'}${m.kind==='code'?'</pre>':'</div>'}</section>`;}
if(id==='types'||id==='pit')html+=`<p>${esc($('#'+(id==='types'?'before':'after')+'-summary').textContent)}</p>`;
if(id==='main2'){html+='<h3>Guided tutor record</h3>';for(const kind of ['flat','nested']){const t=state.tutor[kind];html+=`<p>${kind==='flat'?'Selection chain':'Nested selection'}: ${t?esc(t.visited.join(', ')):'Not viewed'}. These are visited example/line identifiers, not marks.</p>`;}}
if(id==='extension')html+=`<p>June 2024 9210/2 Q05.1–05.3, pp. 8–9. Paper answers are on the handed-in sheet, not collected by this app. No digital answer boxes were provided.</p><ul>${state.paper.length?state.paper.map(x=>`<li>${esc(x.action)} · ${esc(x.time)}</li>`).join(''):'<li>No handover recorded.</li>'}</ul>`;
for(const item of evidence.filter(x=>x.stage===id))html+=`<figure class="report-image"><img src="${item.data}" alt="${esc(item.caption||item.name)}"><figcaption>${esc(item.name)}${item.caption?' — '+esc(item.caption):''}</figcaption></figure>`;
}
html+='<h2>Practice check history</h2><p>All recorded checks are preserved, including first attempts and improvements. These are practice counts, not official exam marks.</p>';
if(!state.attempts.length)html+='<p>No checks recorded.</p>';
for(const [i,a]of state.attempts.entries()){html+=`<h3>Check ${i+1} · ${esc(a.group)} · ${esc(a.time)}</h3><p>${a.correct}/${a.total} correct; ${a.attempted} attempted.</p>`;for(const [id,v]of Object.entries(a.answers))html+=`<section class="report-entry"><h3>${esc(registry[id]?.label||id)}</h3><div class="report-answer">${esc(v?prettyValue(id,v):'Not answered at this check.')}</div></section>`;}
html+='<h2>Source and submission notes</h2><p>Original lesson explanations informed by OxfordAQA textbook printed pp. 30–41; specification sections above. Optional paper: June 2024 Q05, checked against official mark scheme p. 10. Any teacher help on the paper should be recorded on the paper.</p><p>Save this PDF, then attach it to the teacher’s Week 4 assignment in Microsoft Teams and select Turn in where provided. Check the confirmation. Exporting alone does not submit your work.</p>';return html;}
